import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNumber, address actor, uint256 ts) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(ts > block.timestamp);
        uint256 n = bound(blockNumber, 0, 10_000_000);

        vm.roll(n);
        vm.warp(ts);
        vm.deal(actor, 10 ether);

        bool ok;
        vm.prank(actor);
        (ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // General rule: balance is fully paid out iff block.number % 15 == 0.
        assertTrue((n % 15 == 0) == (address(c).balance == 0));
    }
