pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint64 ts, uint64 bn, address actor) public {
        // admissible domain: a real actor distinct from the contract, a strictly
        // increasing timestamp, and a block number in the payout regime (%15==0)
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        ts = bound(ts, 1, type(uint64).max / 2);
        bn = bound(bn, 1, 1_000_000) * 15; // still fuzzer-chosen, always a positive multiple of 15

        vm.roll(bn);
        vm.warp(ts); // block.timestamp > 0 == initial pastBlockTime, so require passes

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");

        // general rule: an admissible payout call succeeds and drains the whole
        // contract balance; the mutant (transfer deleted) keeps balance > 0.
        assertTrue(ok && address(c).balance == 0);
    }
}

